br=branch[status]
bus_ids=bus[:,0].astype(int)
idx={b:i for i,b in enumerate(bus_ids)}
nb=len(bus_ids)
parent=list(range(nb))
rank=[0]*nb

def find(a):
    while parent[a]!=a:
        parent[a]=parent[parent[a]]
        a=parent[a]
    return a

def union(a,b):
    ra,rb=find(a),find(b)
    if ra==rb: return
    if rank[ra]<rank[rb]:
        parent[ra]=rb
    elif rank[ra]>rank[rb]:
        parent[rb]=ra
    else:
        parent[rb]=ra
        rank[ra]+=1

for fb,tb in br[:,0:2].astype(int):
    union(idx[fb], idx[tb])

roots={find(i) for i in range(nb)}
print('components', len(roots))
# Compute load/gen totals per component
Pd=bus[:,2]
gen=np.array(d['gen'],float)
Pmax=gen[:,8]
status_g=gen[:,7]>0.5
comp_load={}
comp_gen={}
for i in range(nb):
    r=find(i)
    comp_load[r]=comp_load.get(r,0.0)+Pd[i]

for g in range(gen.shape[0]):
    if not status_g[g]:
        continue
    b=int(gen[g,0])
    r=find(idx[b])
    comp_gen[r]=comp_gen.get(r,0.0)+Pmax[g]

# report components with potential shortage
bad=[]
for r in roots:
    load=comp_load.get(r,0.0)
    cap=comp_gen.get(r,0.0)
    if cap+1e-6 < load:
        bad.append((r,load,cap))
print('components with Pmax<load', len(bad))
if bad:
    bad=sorted(bad, key=lambda x: x[1]-x[2], reverse=True)
    for r,load,cap in bad[:10]:
        print('shortage', load-cap, 'load', load, 'cap', cap)
